<?php
/** Front-end Mobile App management for the Surfside staff dashboard. */
if (!defined('ABSPATH')) { exit; }

function surfside_tools_staff_mobile_app_shortcode() {
    surfside_tools_prevent_cache();
    surfside_tools_staff_enqueue_styles();
    if (!is_user_logged_in()) return surfside_tools_staff_login_box('Please log in to manage the mobile app.');
    if (!current_user_can('upload_files')) return '<div class="surfside-staff-shell"><p>You do not have permission to manage the mobile app.</p></div>';
    $saved=false;
    if ($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['surfside_mobile_app_nonce']) && wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['surfside_mobile_app_nonce'])),'surfside_mobile_app_save')) {
        $settings=function_exists('surfside_tools_app_settings')?surfside_tools_app_settings():array();
        $settings['home_hero_image_id']=absint($_POST['home_hero_image_id']??0);
        $settings['home_hero_focal_x']=max(0,min(100,absint($_POST['home_hero_focal_x']??50)));
        $settings['home_hero_focal_y']=max(0,min(100,absint($_POST['home_hero_focal_y']??50)));
        $settings['home_hero_zoom']=max(100,min(200,absint($_POST['home_hero_zoom']??100)));
        update_option('surfside_tools_app_settings',$settings); $saved=true;
    }
    $settings=function_exists('surfside_tools_app_settings')?surfside_tools_app_settings():array();
    $image_id=absint($settings['home_hero_image_id']??0); $image_url=$image_id?wp_get_attachment_image_url($image_id,'large'):'';
    $focal_x=max(0,min(100,absint($settings['home_hero_focal_x']??50))); $focal_y=max(0,min(100,absint($settings['home_hero_focal_y']??50))); $zoom=max(100,min(200,absint($settings['home_hero_zoom']??100)));
    $information=function_exists('surfside_tools_get_site_information')?surfside_tools_get_site_information():array(); $identity=(array)($information['identity']??array()); $tagline=(string)($identity['tagline']??'The Perfect Church for Imperfect People.');
    wp_enqueue_media(); wp_register_script('surfside-mobile-app-dashboard','',array('jquery'),SURFSIDE_TOOLS_VERSION,true); wp_enqueue_script('surfside-mobile-app-dashboard');
    wp_add_inline_script('surfside-mobile-app-dashboard',"jQuery(function($){var frame,drag=false,sx=0,sy=0,startX=50,startY=50,naturalW=0,naturalH=0;var stage=$('#surfside-mobile-hero-stage');function clamp(v){return Math.max(0,Math.min(100,v));}function point(e){var o=e.originalEvent;if(o.touches&&o.touches.length)return{x:o.touches[0].clientX,y:o.touches[0].clientY};return{x:e.clientX,y:e.clientY};}function geometry(){var r=stage[0].getBoundingClientRect(),z=(+$('#surfside-mobile-zoom').val()||100)/100;if(!naturalW||!naturalH)return{w:r.width,h:r.height};var scale=Math.max(r.width/naturalW,r.height/naturalH)*z;return{w:naturalW*scale,h:naturalH*scale};}function cssPosition(focal,imageSize,viewSize){if(Math.abs(imageSize-viewSize)<.5)return 50;var offset=viewSize/2-(focal/100)*imageSize;return clamp(offset/(viewSize-imageSize)*100);}function sync(){var x=+$('[name=home_hero_focal_x]').val(),y=+$('[name=home_hero_focal_y]').val(),z=+$('#surfside-mobile-zoom').val(),r=stage[0].getBoundingClientRect(),g=geometry();$('#surfside-mobile-zoom-value').text(z+'%');stage.css({'background-size':g.w+'px '+g.h+'px','background-position':cssPosition(x,g.w,r.width)+'% '+cssPosition(y,g.h,r.height)+'%'});}function loadImage(url){naturalW=naturalH=0;if(!url){sync();return;}var img=new Image();img.onload=function(){naturalW=img.naturalWidth;naturalH=img.naturalHeight;sync();};img.src=url;}stage.on('mousedown touchstart',function(e){if(!stage.hasClass('has-image'))return;drag=true;var p=point(e);sx=p.x;sy=p.y;startX=+$('[name=home_hero_focal_x]').val();startY=+$('[name=home_hero_focal_y]').val();stage.addClass('is-dragging');if(e.type==='touchstart')e.preventDefault();});$(document).on('mousemove touchmove',function(e){if(!drag)return;var p=point(e),g=geometry(),x=clamp(startX-(p.x-sx)/g.w*100),y=clamp(startY-(p.y-sy)/g.h*100);$('[name=home_hero_focal_x]').val(Math.round(x));$('[name=home_hero_focal_y]').val(Math.round(y));sync();if(e.type==='touchmove')e.preventDefault();}).on('mouseup touchend touchcancel',function(){drag=false;stage.removeClass('is-dragging');});$('#surfside-mobile-zoom').on('input change',sync);$(window).on('resize',sync);$('#surfside-mobile-position-reset').on('click',function(e){e.preventDefault();$('[name=home_hero_focal_x],[name=home_hero_focal_y]').val(50);$('#surfside-mobile-zoom').val(100);sync();});$('#surfside-mobile-hero-select').on('click',function(e){e.preventDefault();if(frame){frame.open();return;}frame=wp.media({title:'Choose App Home Hero',button:{text:'Use this image'},multiple:false,library:{type:'image'}});frame.on('select',function(){var a=frame.state().get('selection').first().toJSON();$('#surfside-mobile-hero-id').val(a.id);stage.css('background-image','url('+JSON.stringify(a.url)+')').attr('data-image-url',a.url).addClass('has-image');$('#surfside-mobile-hero-remove').show();loadImage(a.url);});frame.open();});$('#surfside-mobile-hero-remove').on('click',function(e){e.preventDefault();$('#surfside-mobile-hero-id').val('0');stage.css('background-image','none').removeClass('has-image').attr('data-image-url','');naturalW=naturalH=0;$(this).hide();sync();});loadImage(stage.attr('data-image-url')||'');});");
    ob_start(); ?>
    <div class="surfside-staff-shell surfside-mobile-app-management">
      <div class="surfside-staff-back"><a href="<?php echo esc_url(surfside_tools_staff_page_url('')); ?>">← Back to Dashboard</a></div>
      <section class="surfside-staff-hero"><p class="surfside-staff-eyebrow">Mobile App</p><h1>Manage Mobile App</h1><p class="surfside-staff-muted">Control app-specific presentation now, with notifications and additional mobile tools added here as the app grows.</p></section>
      <?php if($saved):?><div class="surfside-mobile-notice">App settings saved.</div><?php endif; ?>
      <form method="post"><?php wp_nonce_field('surfside_mobile_app_save','surfside_mobile_app_nonce'); ?>
        <section class="surfside-staff-panel"><h2>Home Experience</h2><p class="surfside-staff-muted">Choose the Home hero image, then drag the photo inside the preview to position it. Use Zoom when you want a tighter crop.</p>
          <input type="hidden" id="surfside-mobile-hero-id" name="home_hero_image_id" value="<?php echo esc_attr($image_id); ?>"><input type="hidden" name="home_hero_focal_x" value="<?php echo esc_attr($focal_x); ?>"><input type="hidden" name="home_hero_focal_y" value="<?php echo esc_attr($focal_y); ?>">
          <div class="surfside-mobile-template-wrap"><div class="surfside-mobile-template-label">APP HOME PREVIEW</div>
            <div id="surfside-mobile-hero-stage" class="surfside-mobile-hero-stage<?php echo $image_url?' has-image':''; ?>" data-image-url="<?php echo esc_attr($image_url); ?>" style="<?php echo $image_url?'background-image:url('.esc_url($image_url).');':''; ?>">
              <div class="surfside-mobile-hero-shade"></div><div class="surfside-mobile-preview-brand"><div class="surfside-mobile-preview-welcome">Welcome home.</div><div class="surfside-mobile-preview-tagline"><?php echo esc_html($tagline); ?></div></div><div class="surfside-mobile-preview-card"><span>COMING UP</span><strong>Upcoming Event</strong><small>Event date · time</small><b>View Events</b></div>
            </div><p class="surfside-staff-muted surfside-mobile-template-help">Drag the image itself to choose what stays in frame. The text and Coming Up card show what the app will cover.</p>
          </div>
          <div class="surfside-mobile-crop-controls"><div><label for="surfside-mobile-zoom"><strong>Zoom</strong> <span id="surfside-mobile-zoom-value"><?php echo esc_html($zoom); ?>%</span></label><input id="surfside-mobile-zoom" name="home_hero_zoom" type="range" min="100" max="200" step="1" value="<?php echo esc_attr($zoom); ?>"></div><button type="button" class="surfside-staff-button-secondary" id="surfside-mobile-position-reset">Center &amp; Reset Zoom</button></div>
          <div class="surfside-mobile-actions"><button type="button" class="surfside-staff-button-secondary" id="surfside-mobile-hero-select"><?php echo $image_id?'Replace Hero Image':'Select Hero Image'; ?></button><button type="button" class="surfside-staff-button-secondary" id="surfside-mobile-hero-remove" style="<?php echo $image_id?'':'display:none;'; ?>">Remove</button></div><p class="surfside-staff-muted">If no image is selected, the app uses its standard branded hero.</p>
        </section><button type="submit" class="surfside-staff-button surfside-mobile-save">Save App Settings</button>
      </form><section class="surfside-staff-panel surfside-mobile-future"><h2>Coming Later</h2><p class="surfside-staff-muted">Push notifications and other app-only controls will live here rather than being buried inside Website Management.</p></section>
    </div>
    <style>.surfside-mobile-template-wrap{max-width:427px;margin:24px auto}.surfside-mobile-template-label{font-size:11px;font-weight:800;letter-spacing:1.5px;color:#176a9a;margin-bottom:8px}.surfside-mobile-hero-stage{position:relative;height:550px;background-color:#0b3f60;background-repeat:no-repeat;border-radius:0 0 32px 32px;overflow:hidden;box-shadow:0 12px 30px rgba(15,45,65,.18);cursor:grab;touch-action:none}.surfside-mobile-hero-stage.is-dragging{cursor:grabbing}.surfside-mobile-hero-shade{position:absolute;inset:0;background:rgba(5,39,61,.64);pointer-events:none}.surfside-mobile-preview-brand{position:absolute;left:20px;right:20px;top:274px;text-align:center;color:#fff;text-shadow:0 1px 5px rgba(0,0,0,.35);pointer-events:none}.surfside-mobile-preview-welcome{font-size:38px;line-height:43px;font-weight:800}.surfside-mobile-preview-tagline{font-size:16px;line-height:22px;margin-top:8px}.surfside-mobile-preview-card{position:absolute;left:20px;right:20px;bottom:34px;padding:16px 20px;border-radius:22px;background:#fff;color:#17212b;display:flex;flex-direction:column;align-items:flex-start;pointer-events:none}.surfside-mobile-preview-card span{font-size:11px;font-weight:800;letter-spacing:1.25px;color:#176a9a}.surfside-mobile-preview-card strong{font-size:23px;line-height:29px;margin:5px 0 0}.surfside-mobile-preview-card small{font-size:14px;line-height:20px;color:#61717d;margin-top:5px}.surfside-mobile-preview-card b{font-size:13px;line-height:16px;color:#fff;background:#176a9a;border-radius:999px;padding:10px 16px;margin-top:13px}.surfside-mobile-template-help{font-size:13px;margin-top:10px}.surfside-mobile-crop-controls{max-width:720px;margin:20px 0 22px;display:grid;grid-template-columns:minmax(240px,1fr) auto;gap:18px;align-items:end}.surfside-mobile-crop-controls label{display:flex;justify-content:space-between;margin-bottom:7px}.surfside-mobile-crop-controls input[type=range]{width:100%}.surfside-mobile-crop-controls .surfside-staff-button-secondary{width:auto;white-space:nowrap}.surfside-mobile-actions{display:flex;gap:10px;flex-wrap:wrap;margin:8px 0 12px}.surfside-mobile-actions .surfside-staff-button-secondary{width:auto}.surfside-mobile-save{width:auto;min-width:190px;border:0;cursor:pointer}.surfside-mobile-notice{padding:14px 18px;margin-bottom:20px;border-radius:10px;background:#eaf7ef;color:#126b36;font-weight:700}.surfside-mobile-future{margin-top:28px}@media(max-width:700px){.surfside-mobile-crop-controls{grid-template-columns:1fr}.surfside-mobile-template-wrap{max-width:360px}.surfside-mobile-hero-stage{height:464px}.surfside-mobile-preview-brand{top:230px}.surfside-mobile-preview-welcome{font-size:32px;line-height:37px}.surfside-mobile-preview-tagline{font-size:14px;line-height:20px}.surfside-mobile-preview-card{left:17px;right:17px;bottom:29px;padding:14px 17px}.surfside-mobile-preview-card strong{font-size:20px;line-height:25px}}</style>
    <?php return ob_get_clean();
}
add_shortcode('surfside_staff_mobile_app','surfside_tools_staff_mobile_app_shortcode');
function surfside_tools_ensure_mobile_app_page(){if(!function_exists('surfside_tools_ensure_staff_page'))return;$dashboard=get_page_by_path('dashboard');if(!$dashboard)return;surfside_tools_ensure_staff_page('Manage Mobile App','mobile-app','[surfside_staff_mobile_app]',(int)$dashboard->ID);} add_action('init','surfside_tools_ensure_mobile_app_page',80);
add_filter('do_shortcode_tag',function($output,$tag){if($tag!=='surfside_staff_dashboard'||!is_user_logged_in()||!current_user_can('upload_files'))return $output;$mobile_button='<a class="surfside-staff-button-secondary surfside-mobile-dashboard-action" href="'.esc_url(surfside_tools_staff_page_url('mobile-app')).'">Manage Mobile App <span class="surfside-staff-arrow">›</span></a>';$website_pattern='(<a class="surfside-staff-button"[^>]*>Manage Website <span class="surfside-staff-arrow">›</span></a>)';if(preg_match('~'.$website_pattern.'~',$output)){$mobile_action='<style>.surfside-mobile-dashboard-action{display:flex!important;width:100%!important;box-sizing:border-box;align-items:center;justify-content:center;margin-top:14px!important;text-align:center;text-decoration:none!important;box-shadow:0 8px 20px rgba(15,45,65,.10)!important}</style>'.$mobile_button;return preg_replace('~'.$website_pattern.'~','$1'.$mobile_action,$output,1);}return $output;},10,2);
